#include <zephyr/ztest.h>
#include <zephyr/fs/fcb.h>
#include <string.h>
#include <stdio.h>

#include "test_fcb.h"

/*
 * This test fills the FCB with elements and verifies that the number of
 * elements counted by fcb_entries_cnt matches the number of elements
 * found by fcb_walk.
 *
 * The original issue might have been due to an incorrect calculation of
 * the maximum number of elements that can fit, or an off-by-one error
 * when dealing with sector boundaries and FCB entry headers. The Kconfig
 * warning about STDOUT_CONSOLE is likely unrelated to this assertion failure.
 *
 * The fix aims to make the element appending logic more robust by
 * dynamically filling the FCB until no space is left, and then comparing
 * the two methods of counting elements. This approach is less prone to
 * errors caused by varying flash configurations or FCB overheads.
 */

/* Global FCB instance for testing, defined in test_fcb.h or similar */
extern struct fcb test_fcb;

/* Test data buffer. TEST_DATA_SIZE is expected to be defined in test_fcb.h */
static uint8_t test_data[TEST_DATA_SIZE];

/* Callback for fcb_walk to count elements */
static int fcb_walk_cb(struct fcb_entry *loc, void *arg)
{
    uint32_t *count = (uint32_t *)arg;
    (*count)++;
    return 0; /* Continue walking */
}

/*
 * Test function for appending and filling FCB with 2 sectors.
 * The name suggests it's part of a test suite that sets up a 2-sector FCB.
